            { width },
            textStyle,
          ]}
        >
          {content}
        </Text>
      )}

      <View style={styles.row}>
        <Text
          style={[styles.text, textStyle, !expanded && styles.flexText]}
          numberOfLines={expanded ? undefined : 1}
        >
          {content}
        </Text>

        {overflows && (
          <Pressable
            accessibilityRole="button"
            accessibilityLabel={expanded ? lessLabel : moreLabel}
            onPress={() => setExpanded((value) => !value)}
            hitSlop={8}
          >
            <Text style={[styles.link, linkStyle]}>
              {expanded ? lessLabel : moreLabel}
            </Text>
          </Pressable>
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  row: {
    flexDirection: 'row',
    alignItems: 'flex-start',
  },
  text: {
    fontSize: 16,
    color: '#222',
  },
  flexText: {
    flex: 1,
    minWidth: 0,
  },
  link: {
    marginLeft: 6,
    color: '#007AFF',
    fontSize: 16,
  },
  measurement: {
    position: 'absolute',
    top: 0,
    left: 0,
    opacity: 0,
  },
});
```

