const ExpandText = ({ text }) => {
  // Split the text into individual lines (ignore empty lines)
  const lines = text.split(/\r?\n/).filter(line => line.trim().length > 0);

  // Internal state: whether the "See more" section is currently visible
  const [expanded, setExpanded] = useState(false);

  return (
    <View style={styles.container}>
      {/* Always show the first line */}
      <Text style={styles.firstLine}>{lines[0] || ''}</Text>

      {/* "See more" button – only meaningful when there are additional lines */}
      <TouchableOpacity
        onPress={() => setExpanded(true)}
        style={styles.button}
      >
        <Text style={styles.buttonText}>See more</Text>
      </TouchableOpacity>

      {/* Show the remaining lines when expanded === true */}
      {expanded && lines.length > 1 && (
        <ScrollView style={styles.remaining}>
          {lines.slice(1).map((line, index) => (
            <Text key={index} style={styles.line}>{line}</Text>
          ))}
        </ScrollView>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
  },
  firstLine: {
    fontSize: 18,
    fontWeight: '600',
    marginBottom: 12,
  },
  button: {
    alignSelf: 'center',
    paddingVertical: 12,
    paddingHorizontal: 24,
    backgroundColor: '#007AFF',
    borderRadius: 6,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.25,
    shadowRadius: 4,
    elevation: 3,
  },
  buttonText: {
    color: '#fff',
    fontWeight: '500',
    fontSize: 16,
  },
  remaining: {
    flex: 1,
    justifyContent: 'center',
  },
  line: {
    fontSize: 16,
    lineHeight: 22,
    marginBottom: 8,
  },
});

export default ExpandText;
```

